<?php
$event = $event ?? (object) [];
$category = $category ?? (object) [];
$participant = $participant ?? (object) [];
$evaluation = $evaluation ?? null;
$criteria = is_array($criteria ?? null) ? $criteria : [];
$positionKey = \grupo_donato_gestao\Services\AcademyEventService::positionKey($participant->position ?? "");
$criteria = array_values(array_filter($criteria, static function ($criterion) use ($positionKey): bool {
    if ((string) ($criterion->scope ?? "general") === "general") return true;
    return $positionKey !== null && (string) ($criterion->scope ?? "") === "position" && (string) ($criterion->position_key ?? "") === $positionKey;
}));
$categoryUrl = get_uri("grupo_donato/operacional/evento/" . (int) $event->id . "/categoria/" . (int) $category->id);
$photoUrl = (($participant->athlete_type ?? "") === "internal" && !empty($participant->student_id) && !empty($participant->photo_path)) ? get_uri("grupo_donato/operacional/foto_aluno/" . (int) $participant->student_id) : get_avatar();
$groups = ["general" => "Avaliação geral", "position" => "Avaliação por posição"];
$breadcrumbs = [["label" => "GD Academy", "url" => get_uri("grupo_donato/operacional?gd_tab=alunos")], ["label" => "Eventos", "url" => get_uri("grupo_donato/operacional?gd_tab=eventos")], ["label" => (string) ($event->name ?? "Evento"), "url" => get_uri("grupo_donato/operacional/evento/" . (int) $event->id)], ["label" => (string) ($category->name ?? "Categoria"), "url" => $categoryUrl . "/avaliacoes"], ["label" => "Avaliação"]];
?>
<?php echo view('grupo_donato_gestao\Operacional\Views\_academy_styles'); ?>
<div id="page-content" class="page-wrapper clearfix gd-academy-page">
    <?php echo view('grupo_donato_gestao\Operacional\Views\_academy_breadcrumbs', ["breadcrumbs" => $breadcrumbs]); ?>
    <div class="gd-academy-header"><div><div class="gd-academy-kicker">Ficha individual</div><h1>Avaliação — <?php echo esc($participant->athlete_name); ?></h1><div class="gd-academy-subtitle"><?php echo esc($category->name); ?> · <?php echo esc($event->name); ?><?php if (!empty($participant->position)): ?> · <?php echo esc($participant->position); ?><?php endif; ?></div></div><div class="gd-academy-header-actions"><img class="gd-academy-avatar" src="<?php echo esc($photoUrl); ?>" alt=""><a class="btn btn-default btn-sm" href="<?php echo esc($categoryUrl . "/avaliacoes"); ?>">← Avaliações</a></div></div>

    <?php echo form_open(get_uri("grupo_donato/operacional/save_event_evaluation"), ["class" => "gd-academy-form-card gd-academy-ajax-form mt20"]); ?><input type="hidden" name="participant_id" value="<?php echo (int) $participant->id; ?>"><?php if ($evaluation): ?><input type="hidden" name="lock_version" value="<?php echo (int) ($evaluation->lock_version ?? 1); ?>"><?php endif; ?><div class="row"><div class="col-md-4 form-group"><label>Classificação</label><select class="form-control" name="performance_classification"><option value="">Selecione</option><?php foreach (["highlight" => "Destaque", "good" => "Bom desempenho", "expected" => "Dentro do esperado", "follow_up" => "Acompanhar"] as $key => $label): ?><option value="<?php echo esc($key); ?>" <?php echo ($evaluation->performance_classification ?? "") === $key ? "selected" : ""; ?>><?php echo esc($label); ?></option><?php endforeach; ?></select></div><div class="col-md-8 form-group"><label>Data da avaliação</label><input class="form-control" value="<?php echo esc($evaluation->evaluated_at ?? date("Y-m-d H:i")); ?>" readonly></div></div>
    <?php foreach ($groups as $groupKey => $groupLabel): $groupCriteria = array_values(array_filter($criteria, static fn($criterion): bool => (string) ($criterion->scope ?? "general") === $groupKey)); if (!$groupCriteria) continue; ?><section class="gd-academy-card mb15"><h3><?php echo esc($groupLabel); ?></h3><div class="row"><?php foreach ($groupCriteria as $criterion): $saved = $criterion->saved_score->score ?? ""; ?><div class="col-md-6 mb15"><label><?php echo esc($criterion->name); ?></label><div class="d-flex align-items-center gap-2"><select class="form-control" name="scores[<?php echo (int) $criterion->id; ?>]" style="max-width:120px"><option value="">—</option><?php for ($score = 1; $score <= 5; $score++): ?><option value="<?php echo $score; ?>" <?php echo (string) $saved === (string) $score || (string) $saved === number_format($score, 1, ".", "") ? "selected" : ""; ?>><?php echo str_repeat("★", $score); ?> (<?php echo $score; ?>)</option><?php endfor; ?></select><span class="gd-academy-muted">1 a 5</span></div></div><?php endforeach; ?></div></section><?php endforeach; ?>
    <div class="row"><div class="col-md-6"><div class="form-group"><label>Pontos fortes</label><textarea class="form-control" name="strengths" rows="4"><?php echo esc($evaluation->strengths ?? ""); ?></textarea></div><div class="form-group"><label>Pontos a desenvolver</label><textarea class="form-control" name="development_areas" rows="4"><?php echo esc($evaluation->development_areas ?? ""); ?></textarea></div></div><div class="col-md-6"><div class="form-group"><label>Recomendação para próximos treinos</label><textarea class="form-control" name="next_training_recommendation" rows="4"><?php echo esc($evaluation->next_training_recommendation ?? ""); ?></textarea></div><div class="form-group"><label>Feedback ao responsável</label><textarea class="form-control" name="responsible_feedback" rows="4"><?php echo esc($evaluation->responsible_feedback ?? ""); ?></textarea></div></div></div><div class="form-group"><label>Comentário geral</label><textarea class="form-control" name="general_comment" rows="4"><?php echo esc($evaluation->general_comment ?? ""); ?></textarea></div><div class="form-group"><label>Observação interna</label><textarea class="form-control" name="internal_note" rows="3"><?php echo esc($evaluation->internal_note ?? ""); ?></textarea></div><div class="gd-academy-sticky-actions"><button class="btn btn-primary" type="submit">Salvar avaliação</button><a class="btn btn-link" href="<?php echo esc($categoryUrl . "/avaliacoes"); ?>">Cancelar</a></div><?php echo form_close(); ?>
</div>
<?php echo view('grupo_donato_gestao\Operacional\Views\_academy_actions'); ?>
